prices = {"notebook": 12.00, "pen_set": 8.40, "mug": 15.00, "tote": 22.00}
rate = 0.15
for item, p in prices.items():
    print(f"{item}: {p:.2f} -> {p * (1 - rate):.2f}")
total = sum(p * (1 - rate) for p in prices.values())
print(f"total after discount: {total:.2f}")

def average(values):
    if not values:
        return None
    return sum(values) / len(values)

print(average([10, 20, 30]))
print(average([]))
